insert into user_account (
  user_id, username, password_hash, password_salt, nickname, email, role, status, create_time, update_time
) values (
  #{userId}, #{username}, #{passwordHash}, #{passwordSalt}, #{nickname}, #{email}, #{role}, #{status},
  #{createTime}, #{updateTime}
)

insert into user_login_session (
  token, user_id, expire_time, status, create_time
) values (
  #{token}, #{userId}, #{expireTime}, #{status}, #{createTime}
)

mapper.update:
update user_login_session
set status = 'INVALID'
where token = #{token}
